code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long result = n;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            while (n % d == 0) {
                n /= d;
            }
            result -= result / d;
        }
    }
    if (n > 1) {
        result -= result / n;
    }
    cout << result << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long result = n;
        for (long d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                while (n % d == 0) {
                    n /= d;
                }
                result -= result / d;
            }
        }
        if (n > 1) {
            result -= result / n;
        }
        System.out.println(result);
    }
}
